r"""
Unicolors Task Diary - one-click update
Adds: attachments + voice note in the brief, and login with email.

HOW TO USE
  1. Put this file in your project folder (the folder that has manage.py).
  2. Open the terminal in that folder and run:
         venv\Scripts\activate
         python update_diary.py
  3. Then start the app as usual:  python manage.py runserver

It makes a backup of every file it changes in a folder called  _backup_<date-time>.
"""
import json
import os
import shutil
import subprocess
import sys
from datetime import datetime

